+function formatTime(ms: number) {
+  const s = ms / 1000;
+  const m = Math.floor(s / 60);
+  const sec = Math.floor(s % 60);
+  const tenths = Math.floor((s * 10) % 10);
+  return `${m}:${String(sec).padStart(2, "0")}.${tenths}`;
+}
+
+function ordinal(n: number) {
+  const s = ["th", "st", "nd", "rd"];
+  const v = n % 100;
+  return n + (s[(v - 20) % 10] ?? s[v] ?? s[0]);
+}
