+let firstLoad = 0;
+for (const rel of pageFiles) {
+  if (!rel.endsWith(".js")) continue;
+  const file = path.join(NEXT, rel);
+  if (!existsSync(file)) continue;
+  firstLoad += gzipSync(await readFile(file)).length;
+}
